sys_ws_operation.operation_script:
(function process(request, response) {
  var email = gs.getUser().getEmail();
  var gr = new GlideRecord('x_2056099_indust_0_cust_master');
  gr.addQuery('primary_contact_email', email);
  gr.addActiveQuery();
  gr.setLimit(1);
  gr.query();
  if (gr.next()) {
    response.setBody({
      linked: true,
      customer: {
        sys_id: gr.getUniqueValue(),
        customer_name: gr.getValue('customer_name'),
        customer_id: gr.getValue('customer_id'),
        primary_contact_email: gr.getValue('primary_contact_email'),
        primary_contact_phone: gr.getValue('primary_contact_phone'),
        customer_type: gr.getDisplayValue('customer_type'),
        payment_terms: gr.getDisplayValue('payment_terms'),
        credit_limit: gr.getDisplayValue('credit_limit'),
        industry: gr.getValue('industry'),
        notes: gr.getValue('notes'),
        active: gr.getValue('active')
      }
    });
  } else {
    response.setBody({
      linked: false,
      userEmail: email,
      message: 'No customer account is linked to your email address (' + email + '). Please contact your account administrator.'
    });
  }
})(request, response)
